add_action( 'woocommerce_cart_actions', 'perfectpixel_empty_cart_button' );
add_action( 'wp_loaded', 'perfectpixel_empty_cart_handle', 20 );

function perfectpixel_empty_cart_button() {
	$url = wp_nonce_url( add_query_arg( 'perfectpixel_empty_cart', '1', wc_get_cart_url() ), 'perfectpixel_empty_cart' );
	printf(
		'<a href="%1$s" class="button perfectpixel-empty-cart" onclick="return confirm(%2$s);">%3$s</a>',
		esc_url( $url ),
		esc_attr( wp_json_encode( '{{empty_cart_confirm}}' ) ),
		esc_html( '{{empty_cart_label}}' )
	);
}

function perfectpixel_empty_cart_handle() {
	if ( empty( $_GET['perfectpixel_empty_cart'] ) || ! function_exists( 'WC' ) || ! WC()->cart ) { // phpcs:ignore WordPress.Security.NonceVerification
		return;
	}
	if ( isset( $_GET['_wpnonce'] ) && wp_verify_nonce( sanitize_key( $_GET['_wpnonce'] ), 'perfectpixel_empty_cart' ) ) {
		WC()->cart->empty_cart();
	}
	wp_safe_redirect( wc_get_cart_url() );
	exit;
}
